class Solution {
public:
    bool validateStackSequences(vector<int>& pushed, vector<int>& popped) {
        int top = -1;
        int popIdx = 0;
        int n = (int)pushed.size();
        for (int i = 0; i < n; i++) {
            pushed[++top] = pushed[i];
            while (top >= 0 && pushed[top] == popped[popIdx]) {
                top--;
                popIdx++;
            }
        }
        return popIdx == n;
    }
};
